
import 'package:uuid/uuid.dart';
final _uuid=Uuid();
class ProjectModel{String id;String name;String color;ProjectModel({required this.id, required this.name, required this.color}); factory ProjectModel.create(String name)=>ProjectModel(id:_uuid.v4(), name:name, color:'#7C3AED'); Map<String,dynamic> toMap()=>{'id':id,'name':name,'color':color}; factory ProjectModel.fromMap(Map m)=>ProjectModel(id:m['id'], name:m['name'], color:m['color']??'#7C3AED');}
class TaskModel{String id;String title;String? desc;String projectId;String status;DateTime createdAt;DateTime? dueDate;int pomodoroCount;int priority;TaskModel({required this.id, required this.title, this.desc, required this.projectId, required this.status, required this.createdAt, this.dueDate, this.pomodoroCount=0, this.priority=1}); factory TaskModel.create({required String title, required String projectId})=>TaskModel(id:_uuid.v4(), title:title, projectId:projectId, status:'todo', createdAt:DateTime.now()); Map<String,dynamic> toMap()=>{'id':id,'title':title,'desc':desc,'projectId':projectId,'status':status,'createdAt':createdAt.toIso8601String(),'dueDate':dueDate?.toIso8601String(),'pomodoroCount':pomodoroCount,'priority':priority}; factory TaskModel.fromMap(Map m)=>TaskModel(id:m['id'], title:m['title'], desc:m['desc'], projectId:m['projectId'], status:m['status'], createdAt:DateTime.parse(m['createdAt']), dueDate:m['dueDate']!=null?DateTime.parse(m['dueDate']):null, pomodoroCount:m['pomodoroCount']??0, priority:m['priority']??1);}
class WalletModel{String id;String name;double balance;String type;String color;WalletModel({required this.id, required this.name, required this.balance, required this.type, required this.color}); factory WalletModel.create(String n,double b)=>WalletModel(id:_uuid.v4(), name:n, balance:b, type:'cash', color:'#7C3AED'); Map<String,dynamic> toMap()=>{'id':id,'name':name,'balance':balance,'type':type,'color':color}; factory WalletModel.fromMap(Map m)=>WalletModel(id:m['id'], name:m['name'], balance:(m['balance'] as num).toDouble(), type:m['type'], color:m['color']);}
class TransactionModel{String id;String walletId;double amount;String type;String category;String? note;DateTime date;TransactionModel({required this.id, required this.walletId, required this.amount, required this.type, required this.category, this.note, required this.date}); factory TransactionModel.create({required String walletId, required double amount, required String type, required String cat})=>TransactionModel(id:_uuid.v4(), walletId:walletId, amount:amount, type:type, category:cat, date:DateTime.now()); Map<String,dynamic> toMap()=>{'id':id,'walletId':walletId,'amount':amount,'type':type,'category':category,'note':note,'date':date.toIso8601String()}; factory TransactionModel.fromMap(Map m)=>TransactionModel(id:m['id'], walletId:m['walletId'], amount:(m['amount'] as num).toDouble(), type:m['type'], category:m['category'], note:m['note'], date:DateTime.parse(m['date']));}
class BudgetModel{String id;String category;double limit;double spent;String period;BudgetModel({required this.id, required this.category, required this.limit, required this.spent, required this.period}); factory BudgetModel.create(String c,double l)=>BudgetModel(id:_uuid.v4(), category:c, limit:l, spent:0, period:'monthly'); Map<String,dynamic> toMap()=>{'id':id,'category':category,'limit':limit,'spent':spent,'period':period}; factory BudgetModel.fromMap(Map m)=>BudgetModel(id:m['id'], category:m['category'], limit:(m['limit'] as num).toDouble(), spent:(m['spent'] as num).toDouble(), period:m['period']);}
class DebtModel{String id;String person;double amount;String type;DateTime dueDate;bool paid;DebtModel({required this.id, required this.person, required this.amount, required this.type, required this.dueDate, required this.paid}); factory DebtModel.create(String p,double a)=>DebtModel(id:_uuid.v4(), person:p, amount:a, type:'owe', dueDate:DateTime.now().add(const Duration(days:30)), paid:false); Map<String,dynamic> toMap()=>{'id':id,'person':person,'amount':amount,'type':type,'dueDate':dueDate.toIso8601String(),'paid':paid}; factory DebtModel.fromMap(Map m)=>DebtModel(id:m['id'], person:m['person'], amount:(m['amount'] as num).toDouble(), type:m['type'], dueDate:DateTime.parse(m['dueDate']), paid:m['paid']);}
class HabitModel{String id;String name;String icon;String color;List<String> completedDates;int streak;HabitModel({required this.id, required this.name, required this.icon, required this.color, required this.completedDates, required this.streak}); factory HabitModel.create(String n)=>HabitModel(id:_uuid.v4(), name:n, icon:'⭐', color:'#10B981', completedDates:[], streak:0); Map<String,dynamic> toMap()=>{'id':id,'name':name,'icon':icon,'color':color,'completedDates':completedDates,'streak':streak}; factory HabitModel.fromMap(Map m)=>HabitModel(id:m['id'], name:m['name'], icon:m['icon'], color:m['color'], completedDates:List<String>.from(m['completedDates']??[]), streak:m['streak']??0);}
class VaultModel{String id;String title;String encryptedContent;DateTime createdAt;VaultModel({required this.id, required this.title, required this.encryptedContent, required this.createdAt}); Map<String,dynamic> toMap()=>{'id':id,'title':title,'encryptedContent':encryptedContent,'createdAt':createdAt.toIso8601String()}; factory VaultModel.fromMap(Map m)=>VaultModel(id:m['id'], title:m['title'], encryptedContent:m['encryptedContent'], createdAt:DateTime.parse(m['createdAt']));}
class GoalModel{String id;String title;String? desc;double progress;DateTime targetDate;bool completed;GoalModel({required this.id, required this.title, this.desc, required this.progress, required this.targetDate, required this.completed}); factory GoalModel.create(String t)=>GoalModel(id:_uuid.v4(), title:t, progress:0, targetDate:DateTime.now().add(const Duration(days:90)), completed:false); Map<String,dynamic> toMap()=>{'id':id,'title':title,'desc':desc,'progress':progress,'targetDate':targetDate.toIso8601String(),'completed':completed}; factory GoalModel.fromMap(Map m)=>GoalModel(id:m['id'], title:m['title'], desc:m['desc'], progress:(m['progress'] as num).toDouble(), targetDate:DateTime.parse(m['targetDate']), completed:m['completed']);}
class JournalModel{String id;String content;String mood;DateTime date;JournalModel({required this.id, required this.content, required this.mood, required this.date}); factory JournalModel.create(String c)=>JournalModel(id:_uuid.v4(), content:c, mood:'😊', date:DateTime.now()); Map<String,dynamic> toMap()=>{'id':id,'content':content,'mood':mood,'date':date.toIso8601String()}; factory JournalModel.fromMap(Map m)=>JournalModel(id:m['id'], content:m['content'], mood:m['mood'], date:DateTime.parse(m['date']));}
class NoteModel{String id;String title;String content;List<String> tags;DateTime updatedAt;NoteModel({required this.id, required this.title, required this.content, required this.tags, required this.updatedAt}); factory NoteModel.create(String t)=>NoteModel(id:_uuid.v4(), title:t, content:'', tags:[], updatedAt:DateTime.now()); Map<String,dynamic> toMap()=>{'id':id,'title':title,'content':content,'tags':tags,'updatedAt':updatedAt.toIso8601String()}; factory NoteModel.fromMap(Map m)=>NoteModel(id:m['id'], title:m['title'], content:m['content'], tags:List<String>.from(m['tags']??[]), updatedAt:DateTime.parse(m['updatedAt']));}
class PrayerLog{String date;Map<String,bool> prayers;int water;double sleepHours;PrayerLog({required this.date, required this.prayers, required this.water, required this.sleepHours}); Map<String,dynamic> toMap()=>{'date':date,'prayers':prayers,'water':water,'sleepHours':sleepHours}; factory PrayerLog.fromMap(Map m)=>PrayerLog(date:m['date'], prayers:Map<String,bool>.from(m['prayers']??{}), water:m['water']??0, sleepHours:(m['sleepHours'] as num?)?.toDouble()??0);}
